async ({ workspace: { read, glob }, git: { status, log, tag, revParse } }) => {
  const [skill, st, lg, tags, branch, pkg, refs] = await Promise.all([
    read(".pi/skills/pit-delivery/SKILL.md", { format: "raw" }),
    status(["--short", "--branch"]),
    log(["--oneline", "-8"]),
    tag(["--sort=-v:refname", "-l", "v*"]),
    revParse(["--abbrev-ref", "HEAD"]),
    read("package.json", { format: "raw", limit: 10 }),
    glob([".pi/skills/pit-delivery/**"]),
  ]);
  return { skill: skill.content, st: st.stdout, lg: lg.stdout, tags: tags.stdout.split("\n").slice(0, 5), branch: branch.stdout, pkg: pkg.content, refs: refs.entries };
}
